    static IEnumerable<Vector3[]> Triangles(MeshFilter mesh){var v=mesh.sharedMesh.vertices;var tris=mesh.sharedMesh.triangles;for(int i=0;i<tris.Length;i+=3)yield return new[]{mesh.transform.TransformPoint(v[tris[i]]),mesh.transform.TransformPoint(v[tris[i+1]]),mesh.transform.TransformPoint(v[tris[i+2]])};}
    static int EdgeCrossings(GameObject root,float elevation)
    {
        var pitch=Find(root,"PitchPivot");pitch.localRotation=Quaternion.Euler(-elevation,0,0);var deck=Find(root,"C127_Exposed_TraverseMesh");var collider=deck.GetComponent<MeshCollider>();if(!collider){collider=deck.gameObject.AddComponent<MeshCollider>();collider.sharedMesh=deck.GetComponent<MeshFilter>().sharedMesh;}
        Physics.SyncTransforms();int hits=0;foreach(var name in new[]{"C127_Exposed_LoadingTray","C127_Exposed_RammerRod","C127_Exposed_RammerRail","C127_Exposed_RammerSpade","C127_Exposed_Projectile","C127_Exposed_PowderCase"}.Where(n=>Find(root,n).gameObject.activeInHierarchy))foreach(var triangle in Triangles(Find(root,name).GetComponent<MeshFilter>()))for(int i=0;i<3;i++){var a=triangle[i];var d=triangle[(i+1)%3]-a;RaycastHit hit;if(d.magnitude>.001f&&collider.Raycast(new Ray(a+d.normalized*.0001f,d.normalized),out hit,d.magnitude-.0002f))hits++;}return hits;
    }
    public static object Run()
    {
        checks=0;var user=SceneManager.GetActiveScene();var before=Snapshot(user);var dirty=user.isDirty;var scene=EditorSceneManager.NewPreviewScene();var rows=new List<object>();var objects=new List<GameObject>();
        try{
            foreach(var twin in new[]{false,true}){
                var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Dir+(twin?"C127_Twin":"C127_Exposed")+"_Turret_Rig.prefab");Check(prefab,"Staged prefab exists");var root=UnityEngine.Object.Instantiate(prefab);SceneManager.MoveGameObjectToScene(root,scene);objects.Add(root);
                Check(root.GetComponentsInChildren<Unit>(true).Length==0&&root.GetComponentsInChildren<Mirage.NetworkIdentity>(true).Length==0,"Staged rigs have no spawnable/network unit");Check(root.GetComponentsInChildren<Transform>(true).All(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)==0),"No missing scripts");
                var guns=root.GetComponentsInChildren<Gun>(true);Check(guns.Length==(twin?2:1),"Independent gun references");Check(guns.All(g=>!g.enabled&&g.Safety&&new SerializedObject(g).FindProperty("ammo").intValue==0&&!new SerializedObject(g).FindProperty("startLoaded").boolValue),"All guns remain disabled,safe,unloaded");Check(root.GetComponentsInChildren<Turret>(true).All(t=>!t.enabled&&!new SerializedObject(t).FindProperty("attachedUnit").objectReferenceValue),"No live target/firing control");
                var muzzleList=new List<Transform>();foreach(var gun in guns){var s=new SerializedObject(gun);var muzzle=(Transform)s.FindProperty("muzzles").GetArrayElementAtIndex(0).objectReferenceValue;var recoil=(Transform)s.FindProperty("recoilTransform").objectReferenceValue;muzzleList.Add(muzzle);Check(muzzle&&recoil&&muzzle.IsChildOf(recoil),"Muzzle follows its recoil branch");Check(recoil.localScale==Vector3.one&&gun.transform.localScale==Vector3.one,"Gameplay wrappers retain unit scale");Check(Vector3.Dot(muzzle.forward,Vector3.forward)>.99999f,"Correct +Z muzzle direction");Check(!s.FindProperty("guidedProjectile").objectReferenceValue,"Old Guard staging does not inherit guided ammunition");Check(s.FindProperty("muzzleParticles").arraySize==2,"Flash and smoke prepared");foreach(var ps in gun.GetComponentsInChildren<ParticleSystem>(true)){Check(ps.transform.IsChildOf(muzzle)&&!ps.main.playOnAwake&&!ps.main.loop,"Owned nonautomatic muzzle effect");ps.Play();ps.Simulate(.02f,true,true,true);Check(ps.particleCount>0,"Prepared muzzle emitter actually emits particles");ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}}
                var group=root.GetComponent<LODGroup>();var levels=group.GetLODs();var tris=levels.Select(l=>l.renderers.Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3)).ToArray();Check(group.enabled&&levels.Length==3&&tris[0]>tris[1]&&tris[1]>tris[2],"Meaningful three-level LOD");foreach(var renderer in root.GetComponentsInChildren<MeshRenderer>(true)){Check(levels.Any(l=>l.renderers.Contains(renderer)),"Every model renderer managed");Check(renderer.sharedMaterials.All(m=>m),"Materials preserved");}Check(group.size==16&&group.localReferencePoint==Vector3.up,"Articulation bounds configured");
                var animation=root.GetComponent<Animation>();Check(animation&&!animation.playAutomatically,"Opt-in preview only");var clip=animation.clip;Check(Math.Abs(clip.length-Duration)<.001f,"Reference reload duration");
                if(twin){Check(!root.GetComponentsInChildren<Transform>(true).Any(t=>t.name.Contains("LoadingRound")||t.name.Contains("Rammer")),"No invisible housed loading mechanism added");var rest=muzzleList.Select(m=>m.position).ToArray();clip.SampleAnimation(root,Duration*.09f);for(int i=0;i<2;i++)Check(Vector3.Distance(rest[i],muzzleList[i].position)>.23f,"Both barrels recoil independently");clip.SampleAnimation(root,Duration);for(int i=0;i<2;i++)Check(Vector3.Distance(rest[i],muzzleList[i].position)<.0001f,"Twin returns exactly to rest");}
                else{
                    var block=Find(root,"C127_Exposed_BreechBlock");var recoil=Find(root,"RecoilPivot");var round=Find(root,"C127_Exposed_LoadingRound");var casing=Find(root,"C127_Exposed_EjectedCase");var rammer=Find(root,"C127_Exposed_Rammer");var lift=Find(root,"C127_Exposed_RammerLift");var powder=Find(root,"C127_Exposed_PowderCase");var spade=Find(root,"C127_Exposed_RammerSpade");float rammerRest=rammer.localPosition.y;
                    foreach(var n in new[]{"C127_Exposed_LoadingRound","C127_Exposed_PowderCase","C127_Exposed_Projectile","C127_Exposed_EjectedCase","C127_Exposed_SpentCase"})Check(Find(root,n).localScale==Vector3.one,"Imported zero scales repaired on staged clone");
                    clip.SampleAnimation(root,0);Check(!round.gameObject.activeSelf&&!casing.gameObject.activeSelf,"Ready pose hides temporary ammunition");clip.SampleAnimation(root,Duration*.07f);Check(recoil.localPosition.z<-.1f&&Math.Abs(block.localPosition.z)<.00001f,"Closed breech during recoil");clip.SampleAnimation(root,Duration*.24f);Check(block.localPosition.z<-.00419f,"Wedge opens downward fully");
                    clip.SampleAnimation(root,Duration*.34f);Check(Find(root,"C127_Exposed_SpentCase").GetComponent<Renderer>().bounds.max.z<block.GetComponent<Renderer>().bounds.min.z-.2f,"Spent case physically clears breech before side handoff");
                    clip.SampleAnimation(root,Duration*.477f);Check(!round.gameObject.activeSelf&&!casing.gameObject.activeSelf,"Clear interval between spent and fresh ammunition");clip.SampleAnimation(root,Duration*.50f);Check(round.gameObject.activeSelf&&!casing.gameObject.activeSelf&&block.localPosition.z<-.00419f,"Fresh separate projectile/case appear only after clearance and full opening");
                    float low=float.MaxValue,high=float.MinValue;for(int i=0;i<=100;i++){float phase=Mathf.Lerp(.55f,.77f,i/100f);clip.SampleAnimation(root,Duration*phase);float gap=Vector3.Dot(muzzleList[0].forward,Rim(powder,true)-Rim(spade,false));low=Mathf.Min(low,gap);high=Mathf.Max(high,gap);Check(gap>.015f&&gap<.025f,"Spade tracks case rim within modeled20mm clearance");Check(Math.Abs(lift.localPosition.z)<.000001f,"Spade remains lowered during insertion");}
                    clip.SampleAnimation(root,Duration*.77f);Check(Math.Abs(round.localPosition.y)<.000001f&&Math.Abs(rammerRest-rammer.localPosition.y-.016f)<.00001f,"Single1.6m ram stroke seats both components");clip.SampleAnimation(root,Duration*.89f);Check(Math.Abs(block.localPosition.z)<.00001f&&lift.localPosition.z>.00219f,"Breech secured and spade raised");clip.SampleAnimation(root,Duration*.98f);Check(Math.Abs(rammer.localPosition.y-rammerRest)<.000001f&&!round.gameObject.activeSelf&&!casing.gameObject.activeSelf,"Ready presentation only after rammer withdrawal");
                    for(int cycle=0;cycle<3;cycle++){clip.SampleAnimation(root,0);clip.SampleAnimation(root,Duration*.60f);Check(round.gameObject.activeSelf,"Ammunition reappears on repeated cycles");clip.SampleAnimation(root,Duration);Check(!round.gameObject.activeSelf&&!casing.gameObject.activeSelf,"Repeated cycle retires temporary ammunition");}
                    foreach(var level in new[]{0,1,2}){group.ForceLOD(level);clip.SampleAnimation(root,0);Check(!round.gameObject.activeSelf&&!casing.gameObject.activeSelf,"LOD never reveals inactive ammo");clip.SampleAnimation(root,Duration*.60f);Check(round.gameObject.activeSelf,"Logical reload phase continues at every LOD");}group.ForceLOD(-1);
                    Check(levels.Skip(1).SelectMany(l=>l.renderers).All(r=>!r.transform.parent.name.Contains("Rammer")&&!r.transform.parent.name.Contains("SpentCase")&&!r.transform.parent.name.Contains("PowderCase")&&!r.transform.parent.name.Contains("LoadingRound")&&!r.transform.parent.name.Contains("EjectedCase")&&!r.transform.parent.name.Contains("Projectile")&&!r.transform.parent.name.Contains("Wheel")),"Distant levels remove small reload/crank parts");
                    clip.SampleAnimation(root,0);var crossings=new[]{0,10,20,25,30,35,40,45,50,60,75,85}.Select(angle=>new{angle,edgeCrossings=new[]{0f,.5f,.55f,.60f,.70f,.77f,.85f,.98f}.Max(phase=>{clip.SampleAnimation(root,phase*Duration);return EdgeCrossings(root,angle);})}).ToArray();Find(root,"PitchPivot").localRotation=Quaternion.identity;
                    rows.Add(new{prefab=root.name,triangles=tris,rammerClearance=new[]{low,high},staticPlatformCrossings=crossings});
                }
